package org.schabi.newpipe.custom.cloud

import com.grack.nanojson.JsonArray
import com.grack.nanojson.JsonObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue

/** One shared assertion set for JVM and actual Android; expected transport generated by TypeScript peer. */
class CloudWireAssertions(input: String) {
    private val root = CloudWireJson.obj(input)
    private val vectors = root.getArray("vectors").map { it as JsonObject }
    private fun pages(raw: Any?): List<CloudPages.Page> = (raw as List<*>).map {
        val p = it as Map<*, *>
        CloudPages.Page(p["id"] as String, p["body"] as String)
    }
    fun pageParity() {
        for (v in vectors) {
            val catalog = CloudCatalogCodec.read(CloudWireJson.encode(v["catalog"]))
            val expected = pages(v["pages"])
            val previous = pages(v["previous"])
            val encoded = CloudPages.encode(catalog, previous)
            assertEquals(v.getString("name"), expected, encoded)
            assertEquals(v.getString("name"), v.getString("manifest"), CloudPages.manifest(encoded))
            val decoded = CloudPages.decode(encoded)
            assertEquals(CloudCatalogCodec.fingerprint(catalog), CloudCatalogCodec.fingerprint(decoded.catalog))
        }
    }
    fun uploadParity() {
        for (v in vectors) {
            val expected = v["upload"] as? JsonObject ?: continue
            val h = expected.getObject("header")
            val changes = CloudPages.changes(pages(v["previous"]), pages(v["pages"]))
            val actual = CloudPages.upload(h.getString("mode"), h.getString("sequence"), CloudWireJson.head(h["before"]), h.getString("targetFingerprint"), changes)
            assertEquals(v.getString("name"), CloudWireJson.encode(h), CloudWireJson.encode(actual.header))
            assertEquals(v.getString("name"), CloudWireJson.encode(expected["chunks"]), CloudWireJson.encode(actual.chunks))
        }
    }
    fun sequenceParity() {
        fun key(raw: Any?): CloudKey {
            val o = raw as Map<*, *>
            return CloudKey((o["service"] as Number).toInt(), o["url"] as String)
        }
        fun rows(raw: Any?): List<CloudWireSequence.Row> = (raw as List<*>).map {
            val o = it as Map<*, *>
            CloudWireSequence.Row(o["rank"] as String, key(o["key"]))
        }
        for (v in root.getArray("sequences")) {
            val o = v as JsonObject
            assertEquals(rows(o["after"]), CloudWireSequence.plan(rows(o["before"]), (o["desired"] as List<*>).map(::key)))
        }
    }
    fun jsonRoundTrip() {
        for (v in root.getArray("jsonStrings")) {
            val encoded = CloudWireJson.encode(listOf(v))
            val decoded = CloudWireJson.array(encoded)
            assertEquals(v, decoded[0])
            assertEquals(encoded, CloudWireJson.encode(decoded))
        }
        assertThrows(IllegalArgumentException::class.java) { CloudWireJson.encode("\ud800") }
        assertThrows(IllegalStateException::class.java) { CloudWireJson.encode(1.5) }
    }
    fun corruptionRejected() {
        val baseline = pages(vectors.first { it.getString("name") == "base-new" }["pages"])
        assertThrows(IllegalArgumentException::class.java) { CloudPages.decode(baseline + baseline.first()) }
        assertThrows(IllegalArgumentException::class.java) { CloudPages.decode(baseline.mapIndexed { i, p -> if (i == 0) p.copy(id = "f".repeat(64)) else p }) }
        assertThrows(IllegalArgumentException::class.java) { CloudPages.decode(baseline.map { it.copy(body = it.body + " ") }) }
        assertThrows(IllegalArgumentException::class.java) { CloudPages.decode(emptyList()) }
    }
    fun hintsRemainOutsideSemanticContent() {
        val c = CloudCatalogCodec.read(CloudWireJson.encode(vectors.first { it.getString("name") == "base-new" }["catalog"]))
        val key = c.library.first()
        val hint = CloudMediaHint(key, "Renamed cached title", "Uploader", null, 123, "VIDEO_STREAM")
        val a = CloudPages.encode(c)
        val b = CloudPages.encode(c, a, listOf(hint))
        assertNotEquals(CloudPages.manifest(a), CloudPages.manifest(b))
        assertEquals(CloudCatalogCodec.fingerprint(c), CloudCatalogCodec.fingerprint(CloudPages.decode(b).catalog))
        assertEquals(hint, CloudPages.decode(b).hints.single())
    }
    fun repeatedInsertionIsBounded() {
        val keys = (1..1000).map { CloudKey(0, "https://example.test/item-$it") }.toMutableList()
        var c = CloudCatalog(library = keys.toList())
        var pages = CloudPages.encode(c)
        var maxChanged = 0
        repeat(160) {
            keys.add(500, CloudKey(0, "https://example.test/insert-$it"))
            c = c.copy(library = keys.toList())
            val next = CloudPages.encode(c, pages)
            maxChanged = maxOf(maxChanged, CloudPages.changes(pages, next).size)
            pages = next
        }
        assertTrue(maxChanged <= 6)
        assertTrue(pages.size < 25)
        assertEquals(keys, CloudPages.decode(pages).catalog.library)
        println("CLOUD_ANDROID_PACKING edits=160 max_changed_pages=$maxChanged pages=${pages.size}")
    }
}
